/**
 * Forecourt on PostgreSQL.
 *
 * Draws the same marketplace seed.mjs draws (the same cars, photos, desk and
 * conversations, dated back from the same day) into an empty PostgreSQL
 * database with real types: days as date, moments as timestamp, flags as
 * boolean, photos as bytea, the CHECKs kept. Then it provisions the command
 * journal the inquiry form and the desk's commands write through, and writes
 * `<config>` naming the connection `forecourt`, writable.
 *
 *   node --import tsx test/fixtures/databases/forecourt/seed-postgres.mjs <empty-postgres-url> <new-config.json>
 *
 * The day is today in New York (the App's timezone), or `FORECOURT_TODAY=YYYY-MM-DD`. Requires an empty
 * public schema and never drops or replaces objects. `pg` is an optional
 * repository dependency; this is a development seeder. The SQLite file keeps
 * its migrations (migrations/V1, V2); this schema is their sum, written by
 * hand so no date is text on the engine the App is meant to run on.
 */
import { existsSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import pg from 'pg';
import { migratePostgresCommandJournal } from '@mistriwork/mistri/maintenance';
import { marketplace, TABLES } from './seed.mjs';

const [url, config] = process.argv.slice(2);
if (!url || !config) {
  console.error('Usage: node --import tsx test/fixtures/databases/forecourt/seed-postgres.mjs <empty-postgres-url> <new-config.json>');
  process.exit(1);
}
if (existsSync(resolve(config))) throw new Error(`Refusing to replace ${config}. Choose a new config path.`);

/* In foreign-key order. Every key is an identity, as SQLite's INTEGER PRIMARY
   KEY is a rowid: an inquiry or a line of its conversation inserted by a
   command takes the next number. */
const ID = 'id integer generated by default as identity primary key';
const DDL = [
  `create table dealer (${ID}, name text not null, city text not null, phone text not null, email text not null, about text,
    rating real check (rating between 1 and 5), reviews integer not null default 0 check (reviews >= 0))`,
  `create table vehicle (${ID}, stock_ref text not null unique, title text not null,
    make text not null, model text not null, trim text, engine text, year integer not null,
    price integer not null check (price > 0), mileage integer not null check (mileage >= 0),
    body_type text not null check (body_type in ('Hatchback','Sedan','Wagon','SUV','Coupe','Pickup','Van')),
    fuel text not null check (fuel in ('Gas','Diesel','Hybrid','Electric')),
    transmission text not null check (transmission in ('Manual','Automatic')),
    drivetrain text not null check (drivetrain in ('FWD','RWD','AWD')),
    color text not null, doors integer, seats integer, owners integer,
    status text not null default 'listed' check (status in ('listed','reserved','sold')),
    featured boolean not null default false, highlight text, description text, features text,
    service_records text not null check (service_records in ('Full','Partial')),
    keys integer not null check (keys > 0),
    battery_health integer check (battery_health between 0 and 100),
    est_monthly integer not null check (est_monthly > 0),
    listed_on date not null, dealer_id integer not null references dealer(id),
    version integer not null default 0,
    vin text, interior text, horsepower integer check (horsepower > 0), mpg_city integer check (mpg_city > 0),
    mpg_highway integer check (mpg_highway > 0), range_mi integer check (range_mi > 0), was_price integer check (was_price > 0),
    sold_on date)`,
  `create table vehicle_photo (${ID}, vehicle_id integer not null references vehicle(id), position integer not null,
    caption text not null, file_name text not null, content_type text not null, byte_size integer not null, data bytea not null,
    thumbnail bytea)`,
  `create table saved_vehicle (${ID}, account_id text not null, vehicle_id integer not null references vehicle(id),
    saved_at timestamp not null, active boolean not null default true, version integer not null default 0,
    unique (account_id, vehicle_id))`,
  `create table inquiry (${ID}, reference text not null unique, stock_ref text not null,
    vehicle_id integer references vehicle(id), name text not null, email text not null, phone text, message text not null,
    received_at timestamp not null, account_id text, status text not null default 'new' check (status in ('new','replied','closed')),
    version integer not null default 0,
    stage text not null default 'new' check (stage in ('new','contacted','test_drive','negotiating','won','lost')),
    topic text not null default 'availability' check (topic in ('availability','test_drive','trade_in','financing','price')),
    channel text not null default 'web' check (channel in ('web','account','phone','walk_in')),
    owner text, deal_value integer check (deal_value >= 0), test_drive_at timestamp,
    lost_reason text check (lost_reason in ('bought_elsewhere','price','financing','no_response','sold_to_another')),
    closed_on date)`,
  `create table inquiry_activity (${ID}, inquiry_id integer not null references inquiry(id),
    title text not null, note text not null, actor_id text not null, recorded_at timestamp not null)`,
  `create table inquiry_message (${ID}, inquiry_id integer not null references inquiry(id),
    kind text not null check (kind in ('buyer','reply','note','step')), author text not null, body text not null,
    sent_at timestamp not null, account_id text)`,
  `create table site_image (${ID}, name text not null, file_name text not null, content_type text not null,
    byte_size integer not null, data bytea not null)`,
  'create index vehicle_seller on vehicle(dealer_id)',
  'create index vehicle_photo_vehicle on vehicle_photo(vehicle_id)',
  'create index inquiry_message_inquiry on inquiry_message(inquiry_id)',
  'create index inquiry_vehicle on inquiry(vehicle_id)',
  'create index saved_vehicle_vehicle on saved_vehicle(vehicle_id)',
];
const FLAGS = new Set(['featured']);
const EMPTY = ['saved_vehicle', 'inquiry_activity'];

const rows = marketplace();
const client = new pg.Client({ connectionString: url });
await client.connect();
try {
  await client.query('begin');
  await client.query("SET LOCAL lock_timeout = '5s'");
  const lock = await client.query("SELECT pg_try_advisory_xact_lock(hashtext('tablewalk/forecourt/public')) AS acquired");
  if (!lock.rows[0]?.acquired) throw new Error('Another Forecourt seed is already running.');
  const namespace = await client.query("SELECT oid FROM pg_namespace WHERE nspname = 'public'");
  if (!namespace.rows.length) throw new Error('The public schema must exist before seeding.');
  const existing = await client.query(
    `SELECT 1 FROM pg_class WHERE relnamespace=$1
    UNION ALL SELECT 1 FROM pg_proc WHERE pronamespace=$1 UNION ALL SELECT 1 FROM pg_type WHERE typnamespace=$1 LIMIT 1`,
    [namespace.rows[0].oid],
  );
  if (existing.rows.length) throw new Error('Refusing to seed: the public schema is not empty.');
  await client.query('SET LOCAL search_path = public, pg_catalog');
  for (const statement of DDL) await client.query(statement);
  for (const table of TABLES) {
    const list = rows[table];
    const columns = Object.keys(list[0]);
    const insert = `insert into ${table} (${columns.join(', ')}) values (${columns.map((_, i) => `$${i + 1}`).join(', ')})`;
    for (const row of list)
      await client.query(
        insert,
        columns.map((column) => (FLAGS.has(column) ? Boolean(row[column]) : row[column])),
      );
    console.log(`${table.padEnd(16)} ${list.length}`);
  }
  // The rows came with their ids; the next one a command inserts takes the number after the last.
  for (const table of [...TABLES, ...EMPTY])
    await client.query(`select setval(pg_get_serial_sequence('${table}', 'id'), coalesce((select max(id) from ${table}), 0) + 1, false)`);
  await client.query('commit');
} catch (error) {
  await client.query('rollback').catch(() => {});
  throw error;
} finally {
  await client.end();
}
await migratePostgresCommandJournal(url);
writeFileSync(resolve(config), `${JSON.stringify({ connections: [{ name: 'forecourt', url, writable: true }] }, null, 2)}\n`, {
  flag: 'wx',
  mode: 0o600,
});
console.log(`\nSeeded Forecourt into PostgreSQL; wrote ${config}.`);
